78:           return FadeTransition(
79:             opacity: _fadeController.view,
80:             child: Column(
81:               children: [
82:                 Padding(
83:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
84:                   child: SearchView(onChanged: _filterCurrencies),
85:                 ),
